import "./popover.css";

import type { ComponentProps, ReactNode } from "react";
import { Button, type ButtonVariant } from "./button";
import { cx } from "./cx";

export type PopoverProps = ComponentProps<"div">;

export type PopoverTriggerProps = {
  popoverTarget: string;
  children?: ReactNode;
  className?: string | undefined;
  variant?: ButtonVariant | undefined;
};

export function Popover({ className, ...rest }: PopoverProps) {
  return (
    <div
      popover="auto"
      className={cx("ns-popover", className)}
      {...rest}
    />
  );
}

export function PopoverTrigger({
  popoverTarget,
  children,
  className,
  variant = "outline",
}: PopoverTriggerProps) {
  return (
    <Button variant={variant} className={className} popoverTarget={popoverTarget}>
      {children}
    </Button>
  );
}

@layer components {
  .ns-popover {
    box-sizing: border-box;
    min-width: 10rem;
    margin: 0;
    padding: var(--space-3, 0.39rem);
    border: 1px solid
      var(--line, color-mix(in srgb, var(--text-heading, #111) 18%, transparent));
    border-radius: var(--radius, 0.4rem);
    background: var(--bg-overlay, var(--bg, #fff));
    color: var(--text-body, #444);
    box-shadow: var(--raise);
  }

  .ns-popover:popover-open {
    z-index: var(--z-overlay, 20);
  }
}
